    /// Glyph number of every scalar in `scalars`.
    static let slotByScalar: [UInt32: Int] = {
        var table: [UInt32: Int] = [:]
        var i: Int = 0
        for scalar in VFDGlyphs.scalars {
            table[scalar] = i
            i += 1
        }
        return table
    }()

    /// Glyph number of a scalar, or nil when the font has no glyph for it.
    static func slot(_ scalar: UInt32) -> Int? {
        return slotByScalar[scalar]
    }
}
